import hashlib,json,math,pathlib,sys
P=pathlib.Path(__file__).resolve().parent;rows=[];contrasts=[];excluded=[];pins=[]
for p in sorted(P.glob('dev-*--marginal-channel.json')):
 v=json.loads(p.read_text());assert v['status']=='PASS';pins.append({'file':p.name,'bytes':p.stat().st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()});rows.append({k:v[k] for k in ['opaque_id','d_full','d_prefixmask','extra_channels','first_m_difference','first_CP_difference','marginal_inverse_precision_scale_max_relative_error','marginal_logpdf_max_error','body_wall_s']})
 i=v['first_m_difference']
 if i is None:continue
 point=next(x for x in v['points'] if x['index']==i);mf,mp=point['FF_m'],point['PF_m']
 if min(mf,mp)<=0:excluded.append({'opaque_id':v['opaque_id'],'index':i,'reason':'reset_MAP0 uses sum over parents, cannot treat as growthparent0'});continue
 a=next(x for x in point['parents'] if x['parent']==mf-1);b=next(x for x in point['parents'] if x['parent']==mp-1)
 if min(a['FF_parent_posterior'],b['FF_parent_posterior'],a['PF_parent_posterior'],b['PF_parent_posterior'])<=0 or any(z is None for z in [a['FF_joint_logpdf_authoritative'],b['FF_joint_logpdf_authoritative'],a['PF_logpdf_authoritative'],b['PF_logpdf_authoritative']]):excluded.append({'opaque_id':v['opaque_id'],'index':i,'reason':'zero support/pdf underflow; keep raw state rows'});continue
 rf=math.log(a['FF_parent_posterior'])-math.log(b['FF_parent_posterior']);rp=math.log(a['PF_parent_posterior'])-math.log(b['PF_parent_posterior']);lf=a['FF_joint_logpdf_authoritative']-b['FF_joint_logpdf_authoritative'];lp=a['PF_logpdf_authoritative']-b['PF_logpdf_authoritative'];feedback=rf-rp;extra=a['conditional_extra_logpdf']-b['conditional_extra_logpdf'];err=abs((rf+lf)-(rp+lp)-(feedback+extra));assert err<2e-10
 contrasts.append({'opaque_id':v['opaque_id'],'index':i,'FF_MAP':mf,'PF_MAP':mp,'FF_log_growth_ratio_FFparent_over_PFparent':rf+lf,'PF_log_growth_ratio_FFparent_over_PFparent':rp+lp,'delta_feedback_Rparent_log_ratio':feedback,'delta_conditional_extra_logpdf_ratio':extra,'decomposition_abs_error':err,'source':p.name+'#/points/'+str(v['points'].index(point)),'interpretation':'Relative density ratio between two parents on same current X/d; combined with previous run-length posterior; components interact and are not independent physical causes'})
value={'status':'COMPLETE' if len(rows)==30 else 'PARTIAL','cases':rows,'source_files':pins,'cases_with_extra_channels':sum(bool(v['extra_channels']) for v in rows),'cases_with_first_m_difference':sum(v['first_m_difference'] is not None for v in rows),'cases_with_first_CP_difference':sum(v['first_CP_difference'] is not None for v in rows),'max_Psi_common_relative_error':max(v['marginal_inverse_precision_scale_max_relative_error'] for v in rows),'max_common_predictive_logpdf_error':max(v['marginal_logpdf_max_error'] for v in rows),'first_m_contrasts':contrasts,'first_m_contrast_excluded':excluded,'statistical_meaning':'Common-feature prior is marginally coherent under native defaults and exactly matched common processed histories; extra channels add conditional likelihood and alter accumulated posterior. This is model attribution, not evidence that the static default prior is defective or physical alarms correct. Absolute logdensity signs depend on units; only within-space parent ratios interpreted.'}
q=P/sys.argv[1];assert not q.exists();q.write_text(json.dumps(value,ensure_ascii=False,indent=2)+'\n');print(json.dumps({k:value[k] for k in ['status','cases_with_extra_channels','cases_with_first_m_difference','cases_with_first_CP_difference','max_Psi_common_relative_error','max_common_predictive_logpdf_error']},ensure_ascii=False))
